61	pub(crate) fn duplicate_union_member<'a>(checker: &Checker, expr: &'a Expr) {
62	    let mut seen_nodes: HashSet<ComparableExpr<'_>, _> = FxHashSet::default();
63	    let mut unique_nodes: Vec<&Expr> = Vec::new();
64	    let mut diagnostics = Vec::new();
65	
66	    let mut union_type = UnionKind::TypingUnion;
67	    let mut optional_present = false;
68	    // Adds a member to `literal_exprs` if it is a `Literal` annotation
69	    let mut check_for_duplicate_members = |expr: &'a Expr, parent: &'a Expr| {
70	        if matches!(parent, Expr::BinOp(_)) {
71	            union_type = UnionKind::PEP604;
72	        }
73	
74	        let virtual_expr = if is_optional_type(checker, expr) {
75	            // If the union member is an `Optional`, add a virtual `None` literal.
76	            optional_present = true;
77	            &VIRTUAL_NONE_LITERAL
78	        } else {
79	            expr
80	        };
81	
82	        // If we've already seen this union member, raise a violation.
83	        if seen_nodes.insert(virtual_expr.into()) {
84	            unique_nodes.push(virtual_expr);
85	        } else {
86	            diagnostics.push(checker.report_diagnostic(
87	                DuplicateUnionMember {
88	                    duplicate_name: checker.generator().expr(virtual_expr),
89	                },
90	                // Use the real expression's range for diagnostics.
91	                expr.range(),
92	            ));
93	        }
94	    };
95	
96	    // Traverse the union, collect all diagnostic members
97	    traverse_union_and_optional(&mut check_for_duplicate_members, checker.semantic(), expr);
98	
99	    if diagnostics.is_empty() {
100	        return;
101	    }
102	
103	    // Do not reduce `Union[None, ... None]` to avoid introducing a `TypeError` unintentionally
104	    // e.g. `isinstance(None, Union[None, None])`, if reduced to `isinstance(None, None)`, causes
105	    // `TypeError: isinstance() arg 2 must be a type, a tuple of types, or a union` to throw.
106	    if unique_nodes.iter().all(|expr| expr.is_none_literal_expr()) && !optional_present {
107	        return;
108	    }
109	
110	    // Mark [`Fix`] as unsafe when comments are in range.
111	    let applicability = if checker.comment_ranges().intersects(expr.range()) {
112	        Applicability::Unsafe
113	    } else {
114	        Applicability::Safe
115	    };
116	
117	    // Generate the flattened fix once.
118	    let fix = if let &[edit_expr] = unique_nodes.as_slice() {
119	        // Generate a [`Fix`] for a single type expression, e.g. `int`.
120	        Some(Fix::applicable_edit(
121	            Edit::range_replacement(checker.generator().expr(edit_expr), expr.range()),
122	            applicability,
123	        ))
124	    } else {
125	        match union_type {
126	            // See redundant numeric union
127	            UnionKind::PEP604 => Some(generate_pep604_fix(
128	                checker,
129	                unique_nodes,
130	                expr,
131	                applicability,
132	            )),
133	            UnionKind::TypingUnion => {
134	                // Request `typing.Union`
135	                let Some(importer) = checker.typing_importer("Union", PythonVersion::lowest())
136	                else {
137	                    return;
138	                };
139	                generate_union_fix(
140	                    checker.generator(),
141	                    &importer,
142	                    unique_nodes,
143	                    expr,
144	                    applicability,
145	                )
146	                .ok()
147	            }
148	        }
149	    };
150	
151	    if let Some(fix) = fix {
152	        for diagnostic in &mut diagnostics {
153	            diagnostic.set_fix(fix.clone());
154	        }
155	    }
156	}
