166	/// Generate a [`Fix`] for two or more type expressions, e.g. `int | float | complex`.
167	fn generate_pep604_fix(
168	    checker: &Checker,
169	    nodes: Vec<&Expr>,
170	    annotation: &Expr,
171	    applicability: Applicability,
172	) -> Fix {
173	    debug_assert!(nodes.len() >= 2, "At least two nodes required");
174	
175	    let new_expr = nodes
176	        .into_iter()
177	        .fold(None, |acc: Option<Expr>, right: &Expr| {
178	            if let Some(left) = acc {
179	                Some(Expr::BinOp(ExprBinOp {
180	                    left: Box::new(left),
181	                    op: Operator::BitOr,
182	                    right: Box::new(right.clone()),
183	                    range: TextRange::default(),
184	                    node_index: ruff_python_ast::AtomicNodeIndex::NONE,
185	                }))
186	            } else {
187	                Some(right.clone())
188	            }
189	        })
190	        .unwrap();
191	
192	    Fix::applicable_edit(
193	        Edit::range_replacement(checker.generator().expr(&new_expr), annotation.range()),
194	        applicability,
195	    )
196	}
